  document.querySelector('#pullShadowBtn').onclick=async()=>{const out=document.querySelector('#connectionStatus');out.textContent='Pulling into shadow only…';try{const p=await M.cloud.pullShadow();M.cloud.applyShadow(p);out.textContent=p.networkError?`Cloud pull stopped after ${p.stoppedAfter}: ${p.networkError}`:`Shadow pull complete${Object.keys(p.errors||{}).length?` · ${Object.keys(p.errors).length} table warning(s)`:''}. Production data was not changed.`;UI.renderConnection()}catch(e){out.textContent=e.message}};
