  tests.push(test('Original plan remains immutable after edit',()=>{const s=P.parse('MAIN SET\n6 x 100 Freestyle',{id:'e'}),hash=s.originalPlan.hash,id=s.blocks[0].items[0].id,n=C.editItem(s,id,{reps:8});U.assert(S.total(n)===800,'edit distance wrong');U.assert(n.originalPlan.hash===hash,'original plan mutated');U.assert(n.currentSource.hash!==s.currentSource.hash,'current source not updated')}));
