  tests.push(test('Charlotte profile derives from canonical work',()=>{const s=P.parse('MAIN SET\n10 x 100 Freestyle',{id:'a'}),ath={id:'cm',full_name:'Charlotte Murphy'},state={adaptationProfiles:[]},d=A.session(s,ath,state);U.assert(d.total===600,`got ${d.total}`)}));
  tests.push(test('Charlotte single long swim scales by work volume',()=>{const s=P.parse('WARM-UP\n500',{id:'char500',course:'SCM'}),ath={id:'cm',full_name:'Charlotte Murphy'},x=A.item(s.blocks[0].items[0],ath,{adaptationProfiles:[]},s);U.assert(x.reps===1&&x.distance===300,`got ${x.reps}x${x.distance}`)}));
