  tests.push(test('Legacy corrupt block tree cannot influence v4 import',()=>{const legacy={sessions:[{id:'s',session_date:'2026-08-15',day_part:'AM',title:'Sat AM',squads:['National'],venue:'AquaGym',pool_course:'SCM',workout:G.SATURDAY_SOURCE,planned_distance:5450}],session_blocks:[{id:'bad',session_id:'s',items:[{reps:1,distance:27800}]}]},s=M.legacy.importSession(legacy,'s');U.assert(S.total(s)===5450,`got ${S.total(s)}`);U.assert(s.metadata.legacyBlockRows===1,'legacy evidence not recorded')}));
  tests.push(test('National current metadata does not inherit unrelated T32 cue',()=>{const legacy={sessions:[{id:'s',session_date:'2026-08-15',day_part:'AM',title:'Sat AM',squads:['National'],venue:'AquaGym',pool_course:'SCM',workout:'WARM-UP\n200',plan_cue:'Published monthly calendar: adjusted · SCWC T32 Squad'}]},s=M.legacy.importSession(legacy,'s');U.assert(s.identity.squads[0]==='National','identity changed');U.assert(!String(s.metadata.planCue||'').includes('SCWC'),'current metadata still contaminated');U.assert(String(s.metadata.legacyPlanCue||'').includes('SCWC'),'legacy evidence was discarded')}));
